What C# code can be used to read an Excel table and display its content in a console application?
Assuming the table is stored in a file named "Benefits.xlsx" and is located in the same directory as the C# program, the following code can be used:
using System;
using System.Data;
using System.Data.OleDb;
class Program
{
    static void Main(string[] args)
    {
        // Connection string for Excel 2007 or later
        string connString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=Benefits.xlsx;Extended Properties='Excel 12.0 Xml;HDR=YES'";
        // SQL query to select all rows from the table
        string query = "SELECT * FROM [Sheet1$]";
        // Create a new OleDbConnection object and open it
        OleDbConnection conn = new OleDbConnection(connString);
        conn.Open();
        // Create a new OleDbCommand object with the SQL query and the connection object
        OleDbCommand cmd = new OleDbCommand(query, conn);
        // Create a new OleDbDataAdapter object with the command object
        OleDbDataAdapter adapter = new OleDbDataAdapter(cmd);
        // Create a new DataTable object
        DataTable table = new DataTable();
        // Use the adapter to fill the table
        adapter.Fill(table);
        // Display the table in the console
        foreach (DataRow row in table.Rows)
        {
            foreach (DataColumn col in table.Columns)
            {
                Console.Write("{0,-15}", row[col]);
            }
            Console.WriteLine();
        }
        // Close the connection
        conn.Close();
    }
