import java.util.*;
public class ThreeLargestIntegers {
    public static int[] findThreeLargestIntegers(int[] nums) {
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
            if (pq.size() > 3) {
                pq.poll();
            }
        }
        int[] result = new int[3];
        for (int i = 2; i >= 0; i--) {
            result[i] = pq.poll();
        }
        return result;
    }
    public static void main(String[] args) {
        int[] nums = {4, 2, 9, 7, 5, 8};
        int[] result = findThreeLargestIntegers(nums);
        System.out.println(Arrays.toString(result));
    }
}
```
