Yes, I can definitely help you with that! Here's a sample Swift program that can keep track of the duration of your visits to a particular location, calculate the average duration of all previous visits to that location, and collect data on the weather conditions during your stay:
```swift
import Foundation
// Define a struct to represent a visit to a location
struct Visit {
    var startTime: Date
    var endTime: Date
    var duration: TimeInterval {
        return endTime.timeIntervalSince(startTime)
    }
    var weatherCondition: String
}
// Define a dictionary to store all visits to a location
var visits: [String: [Visit]] = [:]
// Define a function to add a new visit to a location
func addVisit(location: String, startTime: Date, endTime: Date, weatherCondition: String) {
    if visits[location] == nil {
        visits[location] = []
    }
    visits[location]?.append(Visit(startTime: startTime, endTime: endTime, weatherCondition: weatherCondition))
}
// Define a function to calculate the average duration of all previous visits to a location
func calculateAverageDuration(location: String) -> TimeInterval? {
    guard let visitsToLocation = visits[location], !visitsToLocation.isEmpty else {
        return nil
    }
    let totalDuration = visitsToLocation.reduce(0) { $0 + $1.duration }
    return totalDuration / TimeInterval(visitsToLocation.count)
}
// Sample usage
let location = "Central Park"
let startTime = Date(timeIntervalSinceNow: -3600) // 1 hour ago
let endTime = Date()
let weatherCondition = "Sunny"
addVisit(location: location, startTime: startTime, endTime: endTime, weatherCondition: weatherCondition)
if let averageDuration = calculateAverageDuration(location: location) {
    print("Average duration of visits to \(location): \(averageDuration) seconds")
} else {
    print("No visits to \(location) yet")
}
```
In this sample program, we define a `Visit` struct to represent a visit to a location, with properties for the start time, end time, duration, and weather condition. We also define a dictionary `visits` to store all visits to a location, and two functions `addVisit` and `calculateAverageDuration` to add new visits and calculate the average duration of all previous visits to a location, respectively.
