namespace RandomBookGenerator
{
    class Program
    {
        static void Main(string[] args)
        {
            List<Book> books = new List<Book>();
            Random random = new Random();
            // List of possible titles and authors
            string[] titles = { "The Art of Deception", "Hacking Exposed", "Applied Cryptography", "Security Engineering", "Web Application Hacker's Handbook", "Practical Malware Analysis", "Black Hat Python", "Penetration Testing", "The Tangled Web", "Social Engineering" };
            string[] authors = { "Kevin Mitnick", "Stuart McClure", "Bruce Schneier", "Ross Anderson", "Dafydd Stuttard", "Michael Sikorski", "Justin Seitz", "Georgia Weidman", "Michal Zalewski", "Christopher Hadnagy" };
            // Generate 10 unique books
            while (books.Count < 10)
            {
                string title = titles[random.Next(titles.Length)];
                string author = authors[random.Next(authors.Length)];
                string publisher = "Random Publisher";
                int year = random.Next(2000, 2022);
                string isbn = GenerateISBN();
                Book book = new Book(title, author, publisher, year, isbn);
                if (!books.Contains(book))
                {
                    books.Add(book);
                }
            }
            // Print the list of books
            foreach (Book book in books)
            {
                Console.WriteLine("Title: {0}\nAuthor: {1}\nPublisher: {2}\nYear: {3}\nISBN: {4}\n", book.Title, book.Author, book.Publisher, book.Year, book.ISBN);
            }
            Console.ReadLine();
        }
        // Generate a random 13-digit ISBN
        static string GenerateISBN()
        {
            Random random = new Random();
            string isbn = "978";
            while (isbn.Length < 13)
            {
                isbn += random.Next(10).ToString();
            }
            return isbn;
        }
    }
    class Book
    {
        public string Title { get; set; }
        public string Author { get; set; }
        public string Publisher { get; set; }
        public int Year { get; set; }
        public string ISBN { get; set; }
        public Book(string title, string author, string publisher, int year, string isbn)
        {
            Title = title;
            Author = author;
            Publisher = publisher;
            Year = year;
            ISBN = isbn;
        }
        public override bool Equals(object obj)
        {
            if (obj == null || GetType() != obj.GetType())
            {
                return false;
            }
            Book book = (Book)obj;
            return ISBN == book.ISBN;
        }
        public override int GetHashCode()
        {
            return ISBN.GetHashCode();
        }
    }
}
```
