    // Remove stopwords
    unordered_set<string> stop_words = stopwords::get_stopwords("english");
    vector<string> filtered_tokens;
    for (auto token : tokens)
    {
        if (stop_words.find(token) == stop_words.end())
        {
            filtered_tokens.push_back(token);
        }
    }
    // Stem words
    LancasterStemmer stemmer;
    vector<string> stemmed_tokens;
    for (auto token : filtered_tokens)
    {
        stemmed_tokens.push_back(stemmer.stem(token));
    }
    // Join tokens back into text
    ostringstream oss;
    copy(stemmed_tokens.begin(), stemmed_tokens.end(), ostream_iterator<string>(oss, " "));
    string preprocessed_text = oss.str();
    preprocessed_text.erase(preprocessed_text.length() - 1);
    return preprocessed_text;
}
// Function to calculate the formality score of text
double calculate_formality_score(string text)
{
    // Preprocess text
    string preprocessed_text = preprocess_text(text);
    // Load formal and informal word lists
    ifstream formal_file("formal_words.txt");
    ifstream informal_file("informal_words.txt");
    unordered_set<string> formal_words;
    unordered_set<string> informal_words;
    string word;
    while (formal_file >> word)
    {
        formal_words.insert(word);
    }
    while (informal_file >> word)
    {
        informal_words.insert(word);
    }
    // Tokenize text
    casual::EnglishTokenizer tokenizer;
    vector<string> tokens = tokenizer.tokenize(preprocessed_text);
    // Calculate formality score
    double formality_score = 0.0;
    for (auto token : tokens)
    {
        if (formal_words.find(token) != formal_words.end())
        {
            formality_score += 1.0;
        }
        else if (informal_words.find(token) != informal_words.end())
        {
            formality_score -= 1.0;
        }
    }
    formality_score /= tokens.size();
    return formality_score;
}
int main()
{
    // Input text
    string text = "Hey, what's up? How's it going?";
    // Calculate formality score
    auto start_time = chrono::high_resolution_clock::now();
    double formality_score = calculate_formality_score(text);
    auto end_time = chrono::high_resolution_clock::now();
    // Output formality score
    cout << "Formality score: " << formality_score << endl;
    cout << "Time taken: " << chrono::duration_cast<chrono::microseconds>(end_time - start_time).count() << " microseconds" << endl;
    return 0;
}
```
In this code, we first preprocess the text by converting it to lowercase, removing punctuation, tokenizing the text, removing stopwords, and stemming the words. We then load formal and informal word lists and calculate the formality score of the text by counting the number of formal and informal words in the text and dividing by the total number of words in the text. A positive score indicates a formal tone, while a negative score indicates an informal tone.
The code uses the NLTK library to tokenize the text, remove stopwords, and stem the words, which helps to improve the accuracy of the formality score. The code also uses unordered sets to store the formal and informal word lists, which allows for fast lookup of words. Finally, the code uses the chrono library to measure the time taken to calculate the formality score, which helps to ensure that the code is optimized for speed.

